// Verify the calendar calculations with Python to ensure no errors
const fs = require('fs');

// Define holidays and non-working days from the library
const holidays = [
  { date: '2026-01-01', name: 'Confraternização Universal', type: 'feriado' },
  { date: '2026-02-16', name: 'Carnaval', type: 'feriado' },
  { date: '2026-02-17', name: 'Carnaval', type: 'feriado' },
  { date: '2026-02-18', name: 'Quarta-feira de Cinzas', type: 'sem_prazo' },
  { date: '2026-04-03', name: 'Sexta-feira Santa', type: 'feriado' },
  { date: '2026-04-21', name: 'Tiradentes', type: 'feriado' },
  { date: '2026-05-01', name: 'Dia do Trabalho', type: 'feriado' },
  { date: '2026-06-04', name: 'Corpus Christi', type: 'feriado' },
  { date: '2026-09-07', name: 'Independência', type: 'feriado' },
  { date: '2026-10-12', name: 'N. Sra. Aparecida', type: 'feriado' },
  { date: '2026-10-28', name: 'Dia do Servidor Público', type: 'sem_prazo' },
  { date: '2026-11-02', name: 'Finados', type: 'feriado' },
  { date: '2026-11-15', name: 'Proclamação da República', type: 'feriado' },
  { date: '2026-11-20', name: 'Dia Nacional de Zumbi', type: 'feriado' },
  { date: '2026-12-08', name: 'N. Sra. da Conceição (Campinas)', type: 'feriado_municipal' },
  { date: '2026-12-24', name: 'Sem expediente', type: 'sem_prazo' },
  { date: '2026-12-25', name: 'Natal', type: 'feriado' },
  { date: '2026-12-31', name: 'Sem expediente', type: 'sem_prazo' },
  { date: '2027-01-01', name: 'Confraternização Universal', type: 'feriado' },
  { date: '2027-01-25', name: 'Aniversário de SP', type: 'feriado_capital' },
];

const recessStart = '2026-12-20';
const recessEnd = '2027-01-20';

// Check if date is a working day (not holiday, not weekend, not recess)
function isWorkingDay(dateStr) {
  const date = new Date(dateStr + 'T00:00:00');
  const dayOfWeek = date.getDay(); // 0 = Sunday, 6 = Saturday

  // Skip weekends
  if (dayOfWeek === 0 || dayOfWeek === 6) {
    return false;
  }

  // Check holidays
  const holiday = holidays.find(h => h.date === dateStr);
  if (holiday && (holiday.type === 'feriado' || holiday.type === 'feriado_municipal')) {
    return false;
  }

  // Skip recess
  const startDate = new Date(recessStart + 'T00:00:00');
  const endDate = new Date(recessEnd + 'T00:00:00');
  if (date >= startDate && date <= endDate) {
    return false;
  }

  return true;
}

// Count working days between two dates (inclusive of end date)
function countWorkingDays(startDate, endDate) {
  const start = new Date(startDate + 'T00:00:00');
  const end = new Date(endDate + 'T00:00:00');
  let count = 0;

  let current = new Date(start);
  while (current <= end) {
    const dateStr = current.toISOString().split('T')[0];
    if (isWorkingDay(dateStr)) {
      count++;
    }
    current.setDate(current.getDate() + 1);
  }

  return count;
}

// Test cases
console.log('=== Teste 1: Contagem de dias úteis ===');
console.log('Citação disponível: 2026-11-19');
console.log('Citação publicação: 2026-11-23');
console.log('Prazo contestação: 30 dias úteis');
console.log('Vencimento esperado: 2027-01-30');
console.log('Dias úteis calculados:', countWorkingDays('2026-11-23', '2027-01-30'));
console.log('');

console.log('=== Teste 2: Sentença disponível: 2026-12-10 ===');
console.log('Sentença publicação: 2026-12-11');
console.log('Prazo apelação: 30 dias úteis');
console.log('Vencimento esperado: 2027-02-03');
console.log('Dias úteis calculados:', countWorkingDays('2026-12-11', '2027-02-03'));

